/**
 * Renders one deliverable's notices file: a header with a licence summary, then one entry per
 * package with its declared licence and the licence text it ships. The layout is the one the apps'
 * own scripts wrote, so adopting devkit-notices changes only the "generated by" line and the order.
 */
import { compare } from './packages.mjs'

const RULE = '='.repeat(78)
const ENTRY_RULE = '-'.repeat(78)

/** The complete notices text for `title` and its sorted, de-duplicated `packages`. */
export function renderNotices(title, packages) {
  const header = [
    RULE,
    `THIRD-PARTY SOFTWARE NOTICES: ${title}`,
    RULE,
    '',
    'This software includes the open-source packages listed below. Each package',
    'remains under its own license; the full license text follows each entry',
    'where the package ships one. This file is generated by devkit-notices from',
    'the installed production dependencies.',
    '',
    `Total packages: ${packages.length}`,
    'Licenses:',
    ...licenceSummary(packages),
    '',
  ]
  const body = packages.map(renderEntry)
  return `${header.join('\n')}\n${body.join('\n\n')}\n`
}

/** One line per licence, most common first, ties by name. */
function licenceSummary(packages) {
  const counts = new Map()
  for (const record of packages) {
    const license = record.license ?? 'UNKNOWN'
    counts.set(license, (counts.get(license) ?? 0) + 1)
  }
  return [...counts.entries()]
    .sort(
      ([firstName, first], [secondName, second]) =>
        second - first || compare(firstName, secondName),
    )
    .map(([license, count]) => `  ${String(count).padStart(4)}  ${license}`)
}

/** One package's entry. */
function renderEntry(record) {
  const lines = [
    ENTRY_RULE,
    `${record.name}@${record.version}`,
    `License: ${record.license ?? 'UNKNOWN'}`,
  ]
  if (record.publisher) lines.push(`Publisher: ${record.publisher}`)
  if (record.repository) lines.push(`Repository: ${record.repository}`)
  lines.push('')
  lines.push(
    record.text ||
      '(no license file bundled with this package; see the declared license above)',
  )
  return lines.join('\n')
}
